class Badge:
    def __init__(self, label):
        self.label = label
    def rename(self, new_label):
        self.label = new_label
badge = Badge("Learner")
badge.rename("Builder")
print(badge.label)

class Badge:
    def __init__(self, label):
        self.label = label
    def message(self):
        return "Hello " + self.label
badge = Badge("Ava")
print(badge.message())

class Counter:
    def __init__(self, value):
        self.value = value
    def add(self):
        self.value = self.value + 1
a = Counter(0)
b = Counter(10)
a.add()
print(a.value)
print(b.value)

class Buddy:
    def __init__(self, name):
        self.name = name
    def rename(self, name):
        self.name = name
    def greeting(self):
        return "Hi " + self.name
a = Buddy("Ava")
b = Buddy("Sam")
a.rename("Mira")
print(a.greeting())
print(b.greeting())
